pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp, address actor) public {
        // keep values in an admissible, wide domain: block number can far exceed timestamps
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        blockNumber = bound(blockNumber, 1, type(uint128).max);
        timestamp = bound(timestamp, 2, 1000); // small timestamps so blockNumber can dominate

        vm.roll(blockNumber);
        vm.warp(timestamp);
        vm.deal(actor, 20 ether);

        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // one block later, one unit of time later: the rule says a second 10-ether call
        // must succeed, since pastBlockTime is supposed to advance with the timestamp
        vm.roll(blockNumber + 1);
        vm.warp(timestamp + 1);

        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // GENERAL RULE: whenever timestamps strictly increase between accepted calls,
        // the fallback always succeeds. The mutant stored block.number (which can be
        // arbitrarily larger than the timestamp) into pastBlockTime, so the second
        // call's require(block.timestamp > pastBlockTime) reverts.
        assertTrue(ok2, "second call with strictly increasing timestamp must succeed");
    }
}

