import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 seed) public {
        // Choose a fuzzed block number that is a multiple of 15 (admissible domain kept wide).
        uint256 n = bound(seed, 0, type(uint256).max / 15 - 1) * 15;

        address actor = makeAddr("actor");
        vm.deal(actor, 10 ether);

